/* @lc app=leetcode id=2761 lang=kotlin */ class Solution { fun findPrimePairs(n: Int): List<List<Int>> = BooleanArray(n + 1) { true }.apply { if (n >= 0) this[0] = false }.apply { if (n >= 1) this[1] = false }.apply { (2..n).takeWhile { it * it <= n }.forEach { i -> if (this[i]) (i * i..n step i).forEach { j -> this[j] = false } } }.let { p -> (2..n / 2).filter { i -> p[i] && p[n - i] }.map { listOf(it, n - it) } } }